+  static const bool enabled = [] {
+    const char* value = std::getenv("SIRIUS_CANONICAL_FLOAT_SUMS");
+    if (value == nullptr) { return false; }
+    const std::string_view v(value);
+    return v == "1" || v == "true" || v == "TRUE" || v == "on" || v == "ON";
+  }();
+  return enabled;
+}
